#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <errno.h>

// Global shared resources
pthread_spinlock_t spinlock;
volatile int shared_counter = 0;
#define ITERATIONS 50000

void *thread_func(void *arg) {
    long id = (long)arg;
    int i, ret;

    for (i = 0; i < ITERATIONS; i++) {
        // Acquire the lock, spinning if necessary
        if (pthread_spin_lock(&spinlock) != 0) {
            fprintf(stderr, "Thread %ld: Failed to lock\n", id);
            pthread_exit((void*)1);
        }

        // CRITICAL SECTION START
        shared_counter++;
        // CRITICAL SECTION END

        // Release the lock
        if (pthread_spin_unlock(&spinlock) != 0) {
            fprintf(stderr, "Thread %ld: Failed to unlock (Internal Error/UB)\n", id);
            pthread_exit((void*)1);
        }
    }
    return NULL;
}

int main() {
    pthread_t t1, t2;

    // 1. Initialize the spinlock (PTHREAD_PROCESS_PRIVATE ensures synchronization within this process)
    if (pthread_spin_init(&spinlock, PTHREAD_PROCESS_PRIVATE) != 0) {
        perror("pthread_spin_init failed");
        return 1;
    }

    // 2. Create threads
    if (pthread_create(&t1, NULL, thread_func, (void*)1L) != 0) {
        perror("pthread_create t1");
        pthread_spin_destroy(&spinlock);
        return 1;
    }
    if (pthread_create(&t2, NULL, thread_func, (void*)2L) != 0) {
        perror("pthread_create t2");
        pthread_join(t1, NULL);
        pthread_spin_destroy(&spinlock);
        return 1;
    }

    // 3. Wait for threads to finish
    pthread_join(t1, NULL);
    pthread_join(t2, NULL);

    // 4. Destroy the spinlock
    if (pthread_spin_destroy(&spinlock) != 0) {
        perror("pthread_spin_destroy failed");
    }

    printf("Total iterations: %d\n", ITERATIONS * 2);
    printf("Final shared counter value: %d\n", shared_counter);
    return 0;
}
